249	 public:
250	  static Status ReduceScalar(const CollectionSchema::Ptr schema,
251	                             const std::vector<Segment::Ptr> &input_segments,
252	                             const std::string &output_segment_path,
253	                             const std::vector<std::string> &columns,
254	                             const IndexFilter::Ptr &filter,
255	                             bool forward_use_parquet,
256	                             std::function<BlockID()> &block_id_generator,
257	                             roaring::Roaring *delete_row_id_bitmap,
258	                             std::vector<BlockMeta> *output_block_metas,
259	                             uint64_t *min_doc_id, uint64_t *max_doc_id,
260	                             uint32_t *doc_count);
261	
262	  static Status ReduceScalarIndex(
263	      InvertedIndexer::Ptr indexer,
264	      const std::shared_ptr<arrow::RecordBatch> &batch, uint32_t doc_id_offset);
265	
266	  static Status ReduceVectorIndex(
267	      const CollectionSchema::Ptr schema,
268	      const std::vector<Segment::Ptr> &input_segments,
269	      const std::string &output_segment_path, const IndexFilter::Ptr &filter,
270	      std::function<BlockID()> &block_id_generator, uint64_t min_doc_id,
271	      uint64_t max_doc_id, uint32_t doc_count, int concurrency,
272	      std::vector<BlockMeta> *output_block_metas);
273	
274	  // Merges `source_indexers` into a new VectorColumnIndexer at
275	  // `output_index_path`. When the first indexer is eligible for reuse (see
276	  // CanReuseFirstIndexer), its file is copied to the
277	  // output path and opened in-place as the merge base. If `merged_indexer` is
278	  // non-null, it receives the opened indexer (caller owns Close()); otherwise
279	  // the indexer is closed before returning.
280	  static Status MergeWithOptionalReuse(
281	      const std::string &output_index_path, const FieldSchema &index_field,
282	      std::vector<VectorColumnIndexer::Ptr> source_indexers,
283	      const IndexFilter::Ptr &filter, int concurrency,
284	      VectorColumnIndexer::Ptr *merged_indexer);
285	
286	  // Returns a FieldSchema clone whose index_params is ready for building the
287	  // quantize indexer.
288	  //   - HNSW_RABITQ: clones index params, trains a RabitqConverter against
289	  //     `raw_vector_provider`, and attaches the resulting reformer and
290	  //     provider to the cloned params.
291	  //   - IVF_RABITQ: uses the cloned field unchanged because its builder owns
292	  //     KMeans and RaBitQ training.
293	  //   - Other quantize types: clones the field with its current index_params
294	  //     unchanged.
295	  // `raw_vector_provider` must remain alive until an HNSW_RABITQ quantize
296	  // indexer has been flushed; it may be null for other cases.
297	  static Status PrepareQuantizeField(
298	      const FieldSchema &field,
299	      const core::IndexProvider::Pointer &raw_vector_provider,
300	      std::shared_ptr<FieldSchema> *out_field);
301	
302	  // Build a fresh FTS RocksDB under output_segment_path by streaming all
303	  // FTS fields from input_segments through FtsRocksdbReducer.
304	  //   - input_segments: ascending min_doc_id, contiguous doc_id range.
305	  //   - delete_row_id_bitmap: deleted positions in input scan order
306	  //     (shared with the vector path); empty for pure consolidation.
307	  static Status ReduceFts(const CollectionSchema::Ptr &schema,
308	                          const std::vector<Segment::Ptr> &input_segments,
309	                          const std::string &output_segment_path,
310	                          const roaring::Roaring &delete_row_id_bitmap,
311	                          std::function<BlockID()> &block_id_generator,
312	                          std::vector<BlockMeta> *output_block_metas);
313	
314	  static arrow::Status FilterRecordBatch(
315	      const std::shared_ptr<arrow::RecordBatch> &batch,
316	      const IndexFilter::Ptr filter, uint32_t row_id_offset,
317	      std::shared_ptr<arrow::RecordBatch> *filtered,
318	      roaring::Roaring *delete_row_id_bitmap, uint64_t *min_doc_id,
319	      uint64_t *max_doc_id);
320	};
321	
322	}  // namespace zvec
